[{"order":1,"type":"heading","text":"Angular Navigation: routerLink and Router Service"},{"order":2,"type":"paragraph","text":"Angular provides powerful navigation capabilities through the 'routerLink' directive and the 'Router' service. These tools enable you to create single-page applications (SPAs) with seamless transitions between different views or components."},{"order":3,"type":"subheading","text":"Using routerLink for Declarative Navigation"},{"order":4,"type":"paragraph","text":"The 'routerLink' directive is the preferred way to navigate between routes in your templates. It's declarative, meaning you specify the desired route in the HTML, and Angular handles the navigation."},{"order":5,"type":"code","text":"<a routerLink="/home">Home</a>
<a routerLink="/products">Products</a>
<a routerLink="/contact" [queryParams]="{ 'id': 123, 'name': 'example' }">Contact</a>
<a routerLink="/product/42">Product Detail</a>"},{"order":6,"type":"bullet_point","text":"The first example navigates to the '/home' route."},{"order":7,"type":"bullet_point","text":"The second example navigates to the '/products' route."},{"order":8,"type":"bullet_point","text":"The third example navigates to the '/contact' route and passes query parameters 'id' and 'name'."},{"order":9,"type":"bullet_point","text":"The fourth example navigates to a parameterized route '/product/42', where '42' is the product ID."},{"order":10,"type":"subheading","text":"Using the Router Service for Programmatic Navigation"},{"order":11,"type":"paragraph","text":"The 'Router' service allows you to navigate programmatically from your components. This is useful when you need to navigate based on user actions or application logic."},{"order":12,"type":"code","text":"import { Router } from '@angular/router';
import { Component } from '@angular/core';

@Component({
  selector: 'app-my-component',
  template: '<button (click)="goToProducts()">Go to Products</button>'
})
export class MyComponent {
  constructor(private router: Router) {}

  goToProducts() {
    this.router.navigate(['/products']);
  }

  goToProductDetail(id: number) {
    this.router.navigate(['/product', id]);
  }

  goToContact() {
    this.router.navigate(['/contact'], { queryParams: { id: 123, name: 'example' } });
  }

  goHome() {
    this.router.navigateByUrl('/home');
  }
}"},{"order":13,"type":"bullet_point","text":"Inject the 'Router' service into your component's constructor."},{"order":14,"type":"bullet_point","text":"Use the 'router.navigate()' method to navigate to a specific route. Pass an array of path segments."},{"order":15,"type":"bullet_point","text":"For parameterized routes, include the parameter values in the array."},{"order":16,"type":"bullet_point","text":"Pass query parameters using the 'queryParams' property in the navigation options."},{"order":17,"type":"bullet_point","text":"Use 'router.navigateByUrl()' to navigate using a complete URL string."},{"order":18,"type":"subheading","text":"Relative Navigation"},{"order":19,"type":"paragraph","text":"You can perform relative navigation using the 'relativeTo' property in the navigation options. This allows you to navigate relative to the current route."},{"order":20,"type":"code","text":"import { Router, ActivatedRoute } from '@angular/router';
import { Component } from '@angular/core';

@Component({
  selector: 'app-my-component',
  template: '<button (click)="goBack()">Go Back</button>'
})
export class MyComponent {
  constructor(private router: Router, private route: ActivatedRoute) {}

  goBack() {
    this.router.navigate(['../'], { relativeTo: this.route });
  }
}"},{"order":21,"type":"bullet_point","text":"Inject both 'Router' and 'ActivatedRoute' services."},{"order":22,"type":"bullet_point","text":"Use 'relativeTo: this.route' to specify that the navigation is relative to the current route."},{"order":23,"type":"bullet_point","text":"The example navigates one level up in the route hierarchy (e.g., from '/products/details' to '/products')."},{"order":24,"type":"subheading","text":"Summary"},{"order":25,"type":"paragraph","text":"'routerLink' provides a declarative way to handle navigation in templates, while the 'Router' service enables programmatic navigation from components. Understanding both approaches is crucial for building robust and user-friendly Angular applications."}]
